local tbl = {}

for k, v in pairs(t.All.Standard) do
	v.ID = k
	v.NumericIndex = tonumber(k:gmatch("%d+")()) or -1
	tbl[#tbl + 1] = { k, v.NumericIndex }

	local v3 = t3[v.Category]

	if not v3 then
		v3 = tostring(v.Category)
	end

	v.CategoryDisplayName = v3
end

table.sort(tbl, function(p1, p2) --[[ Line: 1218 ]]
	return p1[2] < p2[2]
end)

local v4 = Universe:IsTestRealm()

for k, v in pairs(tbl) do
	local v5 = t.All.Standard[v[1]]

	t.All.Standard[v[1]].MedalNumber = k

	if v4 and (v5.LinkedBadgeID and v5.TestBadgeID) then
		t.All.Standard[v[1]].LinkedBadgeID = v5.TestBadgeID
	end
end

